INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name`, `slug`, `sku_master`, `base_price`, `sale_price`, `warranty_months`, `weight_grams`, `battery_mah`, `battery_wh`, `screen_size`, `description`, `ai_summary`, `total_sold`, `is_active`) VALUES
(1, 2, 1, 'MacBook Air 13 inch M4 2025', 'macbook-air-13-inch-m4-2025', 'MBA-M4-13', 27990000, 26490000, 12, 1240, 4500, 52.6, 13.6, '<p><strong>MacBook Air 13 inch M4 2025</strong> chính hãng Apple, thiết kế tối ưu hiệu năng và trải nghiệm người dùng hiện đại, bảo hành 12 tháng toàn quốc.</p>', '{"pros": ["Siêu nhẹ chỉ 1.24kg, cực kỳ cơ động khi mang đi làm/đi học", "Màn hình sắc nét, hiển thị màu sắc trung thực"], "cons": ["Thời lượng pin ở mức trung bình khi chạy tác vụ cao"], "target_users": "Sinh viên, nhân viên văn phòng và doanh nhân"}', 52, 1),
(2, 2, 1, 'MacBook Air 15 inch M4 2025', 'macbook-air-15-inch-m4-2025', 'MBA-M4-15', 32990000, 31490000, 12, 1510, 5600, 66.5, 15.3, '<p><strong>MacBook Air 15 inch M4 2025</strong> chính hãng Apple, thiết kế tối ưu hiệu năng và trải nghiệm người dùng hiện đại, bảo hành 12 tháng toàn quốc.</p>', '{"pros": ["Trọng lượng cân đối 1.51kg, hoàn thiện cao cấp", "Màn hình sắc nét, hiển thị màu sắc trung thực"], "cons": ["Thời lượng pin ở mức trung bình khi chạy tác vụ cao"], "target_users": "Sinh viên, nhân viên văn phòng và doanh nhân"}', 69, 1),
(3, 2, 1, 'MacBook Air 13 inch M3', 'macbook-air-13-inch-m3', 'MBA-M3-13', 24990000, 22990000, 12, 1240, 4500, 52.6, 13.6, '<p><strong>MacBook Air 13 inch M3</strong> chính hãng Apple, thiết kế tối ưu hiệu năng và trải nghiệm người dùng hiện đại, bảo hành 12 tháng toàn quốc.</p>', '{"pros": ["Siêu nhẹ chỉ 1.24kg, cực kỳ cơ động khi mang đi làm/đi học", "Màn hình sắc nét, hiển thị màu sắc trung thực"], "cons": ["Thời lượng pin ở mức trung bình khi chạy tác vụ cao"], "target_users": "Sinh viên, nhân viên văn phòng và doanh nhân"}', 86, 1),
(4, 2, 1, 'MacBook Air 15 inch M3', 'macbook-air-15-inch-m3', 'MBA-M3-15', 29990000, 27990000, 12, 1510, 5600, 66.5, 15.3, '<p><strong>MacBook Air 15 inch M3</strong> chính hãng Apple, thiết kế tối ưu hiệu năng và trải nghiệm người dùng hiện đại, bảo hành 12 tháng toàn quốc.</p>', '{"pros": ["Trọng lượng cân đối 1.51kg, hoàn thiện cao cấp", "Màn hình sắc nét, hiển thị màu sắc trung thực"], "cons": ["Thời lượng pin ở mức trung bình khi chạy tác vụ cao"], "target_users": "Sinh viên, nhân viên văn phòng và doanh nhân"}', 103, 1),
(5, 4, 1, 'MacBook Pro 14 inch M4', 'macbook-pro-14-inch-m4', 'MBP-M4-14', 39990000, 38490000, 12, 1550, 6000, 72.4, 14.2, '<p><strong>MacBook Pro 14 inch M4</strong> chính hãng Apple, thiết kế tối ưu hiệu năng và trải nghiệm người dùng hiện đại, bảo hành 12 tháng toàn quốc.</p>', '{"pros": ["Trọng lượng cân đối 1.55kg, hoàn thiện cao cấp", "Viên pin dung lượng lớn 72.4Wh cho thời gian sử dụng bền bỉ", "Màn hình sắc nét, hiển thị màu sắc trung thực"], "cons": [], "target_users": "Game thủ, kỹ sư đồ họa và lập trình viên"}', 120, 1),
(6, 4, 1, 'MacBook Pro 14 inch M4 Pro', 'macbook-pro-14-inch-m4-pro', 'MBP-M4P-14', 49990000, 47990000, 12, 1600, 6000, 72.4, 14.2, '<p><strong>MacBook Pro 14 inch M4 Pro</strong> chính hãng Apple, thiết kế tối ưu hiệu năng và trải nghiệm người dùng hiện đại, bảo hành 12 tháng toàn quốc.</p>', '{"pros": ["Trọng lượng cân đối 1.60kg, hoàn thiện cao cấp", "Viên pin dung lượng lớn 72.4Wh cho thời gian sử dụng bền bỉ", "Màn hình sắc nét, hiển thị màu sắc trung thực"], "cons": [], "target_users": "Game thủ, kỹ sư đồ họa và lập trình viên"}', 137, 1),
(7, 4, 1, 'MacBook Pro 14 inch M4 Max', 'macbook-pro-14-inch-m4-max', 'MBP-M4M-14', 79990000, 76990000, 12, 1620, 6000, 72.4, 14.2, '<p><strong>MacBook Pro 14 inch M4 Max</strong> chính hãng Apple, thiết kế tối ưu hiệu năng và trải nghiệm người dùng hiện đại, bảo hành 12 tháng toàn quốc.</p>', '{"pros": ["Trọng lượng cân đối 1.62kg, hoàn thiện cao cấp", "Viên pin dung lượng lớn 72.4Wh cho thời gian sử dụng bền bỉ", "Màn hình sắc nét, hiển thị màu sắc trung thực"], "cons": [], "target_users": "Game thủ, kỹ sư đồ họa và lập trình viên"}', 154, 1),
(8, 4, 1, 'MacBook Pro 16 inch M4 Pro', 'macbook-pro-16-inch-m4-pro', 'MBP-M4P-16', 64990000, 61990000, 12, 2140, 8500, 100.0, 16.2, '<p><strong>MacBook Pro 16 inch M4 Pro</strong> chính hãng Apple, thiết kế tối ưu hiệu năng và trải nghiệm người dùng hiện đại, bảo hành 12 tháng toàn quốc.</p>', '{"pros": ["Hiệu năng mạnh mẽ, hệ thống tản nhiệt tối ưu cho tác vụ nặng", "Viên pin dung lượng lớn 100.0Wh cho thời gian sử dụng bền bỉ", "Màn hình sắc nét, hiển thị màu sắc trung thực"], "cons": ["Trọng lượng 2.14kg hơi đầm khi di chuyển nhiều"], "target_users": "Game thủ, kỹ sư đồ họa và lập trình viên"}', 171, 1),
