INSERT INTO `reviews` (`id`, `user_id`, `product_id`, `order_item_id`, `rating`, `comment`, `admin_reply`, `status`, `created_at`) VALUES
(1, 5, 1, 1, 5, 'Máy siêu nhẹ 1.24kg, RAM 16GB mở chục tab Chrome và chỉnh ảnh vẫn mượt. Pin lướt web được gần 15 tiếng rất hài lòng!', 'Cảm ơn chị Minh Anh đã tin tưởng ủng hộ TechStore ạ!', 'approved', '2026-10-19 10:00:00'),
(2, 6, 6, 2, 5, 'Build Docker và chạy máy ảo trên M4 Pro mát rượi, màn hình XDR 120Hz nhìn quen xong không muốn nhìn màn hình khác luôn.', 'TechStore cảm ơn anh Quốc Bảo đã đánh giá 5 sao cho MacBook Pro M4 Pro!', 'approved', '2026-10-26 14:15:00'),
(3, 6, 226, 3, 5, 'Con lăn MagSpeed cuộn code siêu sướng, bấm êm ru không tiếng động.', NULL, 'approved', '2026-10-26 14:18:00'),
(4, 7, 10, 4, 5, 'Màu Titan bên ngoài sang hơn trong ảnh rất nhiều. Quay video 4K 120fps chống rung đỉnh cao.', 'Cảm ơn chị Ngọc Hân, chúc chị có những thước phim tuyệt đẹp cùng iPhone 16 Pro Max!', 'approved', '2026-11-06 09:40:00'),
(5, 8, 90, 5, 4, 'Legion Slim 5 chiến Cyberpunk 2077 max setting mượt mà, tản nhiệt tốt. Trừ 1 điểm vì cục sạc hơi to.', 'Dạ TechStore ghi nhận góp ý của bạn về kích thước củ sạc 230W công suất cao ạ!', 'approved', '2026-11-12 21:00:00'),
(6, 9, 151, 6, 5, 'Màn hình S24 Ultra chống chói ngoài nắng quá đỉnh, tính năng khoanh tròn tìm kiếm dùng hàng ngày cực tiện.', 'TechStore cảm ơn anh Thanh Tùng đã hài lòng với siêu phẩm Galaxy S24 Ultra!', 'approved', '2026-11-22 08:30:00'),
(7, 10, 186, 7, 5, 'Chất âm Sony WH-1000XM5 quá xuất sắc, chống ồn máy bay êm ru không bị ù tai.', 'Cảm ơn bạn Mai Phương đã đánh giá tai nghe Sony XM5!', 'approved', '2026-11-23 11:00:00'),
(8, 5, 140, 8, 5, 'MSI Prestige 13 nặng chỉ 990g cầm nhẹ như không, mở máy nhận diện gương mặt siêu nhanh.', 'Cảm ơn chị Minh Anh đã lựa chọn dòng laptop siêu nhẹ doanh nhân!', 'approved', '2026-11-25 09:00:00'),
(9, 5, 51, 12, 5, 'Dell XPS 13 viền màn hình siêu mỏng, bàn rê chuột ẩn tương lai nhìn rất sang trọng.', NULL, 'approved', '2026-11-23 18:20:00'),
(10, 6, 44, 13, 5, 'Zephyrus G16 màn hình OLED 240Hz màu sắc rực rỡ, RTX 4070 render video Premiere siêu nhanh.', 'Cảm ơn anh Quốc Bảo đã tin tưởng lựa chọn laptop gaming đồ họa cao cấp!', 'approved', '2026-11-24 16:45:00'),
(11, 7, 232, 14, 5, 'Phím gõ nảy đầm tay, đèn nền tự sáng khi đưa tay tới gần rất thông minh.', NULL, 'approved', '2026-11-25 10:15:00'),
(12, 9, 76, 15, 5, 'Bàn phím ThinkPad gõ sướng nhất phân khúc, máy carbon nhẹ mà chắc chắn.', 'ThinkPad luôn là huyền thoại bàn phím, cảm ơn anh Tùng!', 'approved', '2026-11-25 14:00:00');
