INSERT INTO `ai_chat_logs` (`session_id`, `user_id`, `product_id`, `user_message`, `ai_response`, `created_at`) VALUES
('sess_guest_001', NULL, 1, 'Máy này nặng bao nhiêu và có chơi được game nặng không?', 'MacBook Air 13 M4 chỉ nặng 1.24kg (tương đương khoảng 2.5 chai nước 500ml), rất gọn nhẹ để mang đi học/đi làm. Tuy nhiên máy dùng tản nhiệt thụ động không quạt nên chỉ phù hợp game nhẹ; nếu cần chơi game AAA đồ họa cao, bạn có thể tham khảo Asus ROG Zephyrus G14 hoặc Lenovo Legion Slim 5 nhé!', '2026-11-20 20:10:00'),
('sess_user_005', 5, 140, 'So sánh MSI Prestige 13 AI+ Evo với MacBook Air M4 về cân nặng và pin?', 'MSI Prestige 13 AI+ Evo nhẹ hơn đáng kể với trọng lượng kỷ lục chỉ 990g (so với 1.24kg của MacBook Air M4) và sở hữu viên pin lớn 75Wh cho thời lượng lướt web hỗn hợp rất ấn tượng, rất lý tưởng nếu bạn ưu tiên sự siêu nhẹ tuyệt đối mang theo hàng ngày.', '2026-11-21 10:05:00'),
('sess_user_008', 8, 39, 'Asus ROG Strix G16 và Lenovo Legion Slim 5 con nào card đồ họa mạnh hơn?', 'Lenovo Legion Slim 5 trang bị card đồ họa NVIDIA RTX 4060 8GB VRAM mạnh hơn khoảng 15-20% so với RTX 4050 6GB trên Asus ROG Strix G16, đồng thời nhẹ hơn 100g (2.4kg so với 2.5kg). Tuy nhiên ROG Strix G16 lại có viên pin lớn hơn (90Wh so với 80Wh).', '2026-11-23 19:40:00'),
('sess_guest_002', NULL, 10, 'iPhone 16 Pro Max pin dùng chơi game liên tục được bao lâu?', 'Với viên pin 4685mAh tối ưu cùng chip A18 Pro 3nm, iPhone 16 Pro Max có thể chơi game đồ họa cao liên tục khoảng 8.5 giờ, xem video lên tới 29 giờ và lướt web văn phòng hỗn hợp hơn 20 giờ.', '2026-11-24 11:15:00'),
('sess_guest_003', NULL, 51, 'Dell XPS 13 9340 có đủ cổng cắm USB và HDMI không shop?', 'Dạ chào bạn! Dell XPS 13 9340 hướng tới phong cách tối giản tương lai nên chỉ trang bị 2 cổng Thunderbolt 4 Type-C (hỗ trợ sạc nhanh và xuất hình ảnh DisplayPort). Để cắm thẻ nhớ, chuột có dây hoặc cáp HDMI truyền thống, bạn nên dùng thêm một đầu chuyển Hub Type-C đa năng nhé!', '2026-11-25 09:30:00'),
('sess_user_006', 6, 76, 'ThinkPad X1 Carbon Gen 12 bàn phím có bị nông hơn đời cũ không?', 'Dạ ThinkPad X1 Carbon Gen 12 có hành trình phím 1.5mm được tinh chỉnh với độ nảy xúc giác cực tốt, gõ code lâu không bị mỏi tay và tích hợp thêm rãnh thông gió dưới phím giúp máy luôn mát mẻ.', '2026-11-25 10:45:00'),
('sess_guest_004', NULL, 151, 'Galaxy S24 Ultra có những tính năng AI nào hữu ích cho công việc?', 'Galaxy S24 Ultra tích hợp trọn bộ Galaxy AI gồm: Khoanh tròn để tìm kiếm (Circle to Search), Dịch trực tiếp cuộc gọi hai chiều (Live Translate), Trợ lý ghi chú tóm tắt biên bản họp (Note Assist) và Chỉnh sửa ảnh thông minh tái tạo bố cục.', '2026-11-25 11:20:00'),
('sess_guest_005', NULL, 26, 'Asus Zenbook 14 OLED UX3405CA pin dùng thực tế văn phòng được mấy tiếng?', 'Với viên pin khủng 75Wh kết hợp chip Intel Core Ultra tiết kiệm điện, Zenbook 14 OLED cho thời lượng làm việc văn phòng thực tế (soạn thảo Word, Excel, mở 10 tab web) đạt khoảng 10 - 13 tiếng liên tục, hoàn toàn đáp ứng trọn vẹn 1 ngày làm việc.', '2026-11-25 13:50:00'),
('sess_user_007', 7, 186, 'Sony WH-1000XM5 đeo lâu có bị đau vành tai khi đeo kính không?', 'Dạ tai nghe Sony WH-1000XM5 sử dụng đệm da mềm Soft Fit Leather ôm vừa vặn và giảm áp lực lên đỉnh đầu, bản lề không răng trơn tru nên khi đeo cùng gọng kính vẫn rất êm ái và không bị cấn đau.', '2026-11-25 14:15:00');
